function validate([present, future, budget]) {
  if (present.length < 1 || present.length > 1000) return 'present needs 1 to 1000 prices.';
  if (future.length !== present.length) return 'present and future must have the same length.';
  if (present.some(p => !Number.isInteger(p) || p < 0 || p > 100)) return 'Each present price is between 0 and 100.';
  if (future.some(f => !Number.isInteger(f) || f < 0 || f > 100)) return 'Each future price is between 0 and 100.';
  if (!Number.isInteger(budget) || budget < 0 || budget > 1000) return 'budget is between 0 and 1000.';
  return null;
}

