function maximumProfit(present, future, budget) {
  const dp = new Array(budget + 1).fill(0);

  for (let i = 0; i < present.length; i++) {
    const cost = present[i];
    const gain = future[i] - present[i];
    if (gain <= 0) {
      continue;
    }
    for (let money = budget; money >= cost; money--) {
      dp[money] = Math.max(dp[money], dp[money - cost] + gain);
    }
  }
  return dp[budget];
}

