function maximumProfit(present, future, budget) {
  const n = present.length;
  let best = 0;
  for (let mask = 0; mask < (1 << n); mask++) {
    let spent = 0, worth = 0;
    for (let i = 0; i < n; i++) {
      if (mask & (1 << i)) { spent += present[i]; worth += future[i]; }
    }
    if (spent <= budget && worth - spent > best) best = worth - spent;
  }
  return best;
}

