function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const n = 1000;
    const present = Array.from({ length: n }, () => int(0, 100));
    const future = Array.from({ length: n }, () => int(0, 100));
    const budget = rand() < 0.7 ? int(500, 1000) : int(0, 1000);
    return [present, future, budget];
  }
  const n = int(1, 10);
  const top = rand() < 0.2 ? 100 : int(1, 12);
  const present = Array.from({ length: n }, () => int(0, top));
  const future = present.map(p => Math.min(100, Math.max(0, p + int(-top, top))));
  const budget = rand() < 0.1 ? 0 : int(0, Math.min(1000, 3 * top));
  return [present, future, budget];
}
